/// <summary>
/// PaffH 15.04.25
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(InventItemPurchSetup), DataEventType::Updating)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void InventItemPurchSetup_onUpdating(Common sender, DataEventArgs e)
{
    InventItemPurchSetup inventItemPurchSetup = sender as InventItemPurchSetup;
    for (int i = 1; i <= 4; i++)
    {
        FieldId fieldnum1;
        switch (i)
        {
            case 1:
                fieldnum1 = fieldNum(InventItemPurchSetup, MultipleQty);
                break;
            case 2:
                fieldnum1 = fieldNum(InventItemPurchSetup, LowestQty);
                break;
            case 3:
                fieldnum1 = fieldNum(InventItemPurchSetup, HighestQty);
                break;
            case 4:
                fieldnum1 = fieldNum(InventItemPurchSetup, StandardQty);
                break;
        }
        if (inventItemPurchSetup.orig().(fieldnum1) != inventItemPurchSetup.(fieldnum1))
        {
            // save changeLog POP specific Datamanagement
            NDXPOPspecificDataManagementHistory::saveChangeFromInventTable(
                inventItemPurchSetup.inventTable().RecId
                , inventItemPurchSetup
                , fieldnum1
                , [inventItemPurchSetup.orig().(fieldnum1)]
                , [inventItemPurchSetup.(fieldnum1)]);
        }
    }
}
